#[derive(Clone, Debug)]
struct PocCell {
    id: String, identity_quality: String, ordinal: usize, kind: String,
    language: Option<String>, source: String, source_sha256: String,
    metadata: Value, symbols: Vec<Value>, status: String, diagnostics: Vec<String>,
}
#[derive(Clone, Debug)]
struct PocDocument {
    snapshot: String, notebook: String, source_sha256: String,
    cells: Vec<PocCell>, diagnostics: Vec<String>,
}
fn poc_language(token: &str) -> Option<String> {
    match token.trim().to_lowercase().as_str() {
        "python"|"python3"|"ipython" => Some("python".into()),
        "javascript"|"js"|"deno"|"typescript"|"ts" => Some("javascript".into()),
        "rust"|"evcxr" => Some("rust".into()),
        _ => None, // PoC scope; production must reuse the complete existing language registry.
    }
}
fn cell_language(cell: &Value, root: &Value) -> Option<String> {
    if let Some(t)=cell.pointer("/metadata/spur/code_type").and_then(Value::as_str) {
        return poc_language(t); // An explicit unsupported override cannot fall through.
    }
    [cell.pointer("/metadata/kernelspec/name"),root.pointer("/metadata/kernelspec/name"),root.pointer("/metadata/language_info/name")]
        .into_iter().flatten().filter_map(Value::as_str).find_map(poc_language)
}
fn transport_path(doc: &PocDocument, cell: &PocCell) -> String {
    let ext=match cell.language.as_deref() {Some("python")=>"py",Some("javascript")=>"js",Some("rust")=>"rs",_=>"unknown"};
    format!("poc-cells/{}/{}.{}",blake3::hash(doc.notebook.as_bytes()).to_hex(),blake3::hash(cell.id.as_bytes()).to_hex(),ext)
}
fn normalize_notebook(snapshot: &str, notebook: &str, source: &str) -> Result<PocDocument,String> {
    let root: Value=serde_json::from_str(source).map_err(|e|format!("malformed_notebook: {e}"))?;
    let inputs=root.get("cells").and_then(Value::as_array).ok_or("missing_cells_array")?;
    let mut anonymous:BTreeMap<String,usize>=BTreeMap::new();
    let mut seen=BTreeSet::new();
    let mut cells=Vec::new();
    let mut diagnostics=Vec::new();
    for (ordinal,cell) in inputs.iter().enumerate() {
        let text=match cell.get("source") {
            Some(Value::String(s))=>s.clone(),
            Some(Value::Array(lines))=>{
                if !lines.iter().all(Value::is_string) {return Err(format!("invalid_source_array:{ordinal}"));}
                lines.iter().map(|v|v.as_str().unwrap()).collect::<String>()
            },
            _=>return Err(format!("invalid_cell_source:{ordinal}")),
        };
        let explicit=cell.get("id").and_then(Value::as_str).map(str::trim).filter(|s|!s.is_empty());
        let id=if let Some(id)=explicit {id.to_owned()} else {
            let key=format!("cell-{}",blake3::hash(text.as_bytes()).to_hex());
            let n=anonymous.entry(key.clone()).or_default(); *n+=1;
            if *n==1 {key} else {format!("{key}-{n}")}
        };
        if !seen.insert(id.clone()) {return Err(format!("duplicate_cell_id:{id}"));}
        let kind=cell.get("cell_type").and_then(Value::as_str).ok_or("missing_cell_type")?.to_string();
        let language=if kind=="code" {cell_language(cell,&root)} else {None};
        let status=if kind!="code" {"not_indexed"} else if language.is_none() {"unsupported_language"} else {"pending"};
        let mut cell_diagnostics=Vec::new();
        if explicit.is_none() {cell_diagnostics.push("content_derived_identity: source edits change this ID; identical anonymous occurrences are ambiguous".into());}
        if status=="unsupported_language" {diagnostics.push(format!("unsupported_language:{id}"));}
        cells.push(PocCell{id,identity_quality:if explicit.is_some() {"explicit"} else {"content_derived"}.into(),
            ordinal,kind,language,source_sha256:sha256(&text),source:text,metadata:cell.get("metadata").cloned().unwrap_or(json!({})),
            symbols:Vec::new(),status:status.into(),diagnostics:cell_diagnostics});
    }
    Ok(PocDocument{snapshot:snapshot.into(),notebook:notebook.into(),source_sha256:sha256(source),cells,diagnostics})
}
fn assert_cell_ranges(cell: &PocCell) {
    for symbol in &cell.symbols {
        let start=symbol["byte_start"].as_u64().unwrap() as usize;
        let end=symbol["byte_end"].as_u64().unwrap() as usize;
        assert!(start<=end && end<=cell.source.len(),"range outside decoded cell {}",cell.id);
        assert!(cell.source.is_char_boundary(start)&&cell.source.is_char_boundary(end),"UTF8 boundary");
        assert_eq!(symbol["line_start"].as_u64().unwrap() as usize,cell.source[..start].bytes().filter(|b|*b==b'\n').count()+1);
        assert_eq!(symbol["line_end"].as_u64().unwrap() as usize,cell.source[..end].bytes().filter(|b|*b==b'\n').count()+1);
    }
}
fn extract_document(mut doc: PocDocument) -> PocDocument {
    let positions:Vec<usize>=doc.cells.iter().enumerate().filter(|(_,c)|c.status=="pending").map(|(i,_)|i).collect();
    let sources:Vec<Value>=positions.iter().map(|i|json!({"path":transport_path(&doc,&doc.cells[*i]),"source":doc.cells[*i].source})).collect();
    let results=native(json!({"op":"extract","sources":sources}));
    for (i,result) in positions.into_iter().zip(results.as_array().unwrap()) {
        let cell=&mut doc.cells[i];
        assert_eq!(result["source_sha256"],cell.source_sha256);
        cell.status=result["graph_result"]["status"].as_str().unwrap().into();
        cell.symbols=result["symbols"].as_array().unwrap().clone();
        if cell.status!="ok" {doc.diagnostics.push(format!("cell_extraction_failed:{}",cell.id));}
        assert_cell_ranges(cell);
    }
    doc
}
fn source_ref(doc: &PocDocument,cell: &PocCell,symbol: &Value) -> Value {
    json!({"snapshot_id":doc.snapshot,"notebook_path":doc.notebook,"notebook_source_sha256":doc.source_sha256,
        "cell_id":cell.id,"cell_identity_quality":cell.identity_quality,"cell_language":cell.language,
        "cell_source_sha256":cell.source_sha256,"coordinate_space":"decoded_code_cell_utf8",
        "byte_start":symbol["byte_start"],"byte_end":symbol["byte_end"],"line_start":symbol["line_start"],"line_end":symbol["line_end"]})
}
fn document_value(doc: &PocDocument) -> Value {
    json!({"snapshot_id":doc.snapshot,"notebook_path":doc.notebook,"source_sha256":doc.source_sha256,
        "coverage":if doc.diagnostics.is_empty() {"complete_for_poc_languages"} else {"partial"},"diagnostics":doc.diagnostics,
        "cells":doc.cells.iter().map(|c|json!({"cell_id":c.id,"identity_quality":c.identity_quality,"ordinal":c.ordinal,
            "cell_type":c.kind,"language":c.language,"source_sha256":c.source_sha256,"status":c.status,"diagnostics":c.diagnostics,
            "symbols":c.symbols.iter().map(|s|json!({"symbol":s,"source_ref":source_ref(doc,c,s)})).collect::<Vec<_>>()})).collect::<Vec<_>>()})
}
