fn symbol_identity(symbol: &Value) -> String {
    json!([symbol["entity_name"],symbol["symbol_kind"],symbol["enclosing_scope"]]).to_string()
}
fn duplicate_symbol_identity(cell: &PocCell) -> bool {
    let mut seen=BTreeSet::new();
    cell.symbols.iter().any(|s|!seen.insert(symbol_identity(s)))
}
fn compare_documents(left: &PocDocument, right: &PocDocument) -> Value {
    assert_eq!(left.notebook,right.notebook,"PoC pairs the same notebook path");
    let l:BTreeMap<&str,&PocCell>=left.cells.iter().map(|c|(c.id.as_str(),c)).collect();
    let r:BTreeMap<&str,&PocCell>=right.cells.iter().map(|c|(c.id.as_str(),c)).collect();
    let ids:BTreeSet<&str>=l.keys().chain(r.keys()).copied().collect();
    let mut structures=Vec::new();
    let mut diagnostics=Vec::new();
    let mut requests=Vec::new();
    let mut contexts=Vec::new();
    for id in ids {
        let before=l.get(id).copied();
        let after=r.get(id).copied();
        match (before,after) {
            (None,Some(_))=>structures.push(json!({"cell_id":id,"kind":"cell_added"})),
            (Some(_),None)=>structures.push(json!({"cell_id":id,"kind":"cell_deleted"})),
            (Some(a),Some(b))=>{
                for (changed,kind) in [
                    (a.ordinal!=b.ordinal,"cell_moved"),(a.kind!=b.kind,"cell_type_changed"),
                    (a.language!=b.language,"cell_language_changed"),(a.source_sha256!=b.source_sha256,"cell_source_changed"),
                    (a.metadata!=b.metadata,"cell_metadata_changed")] {
                    if changed {structures.push(json!({"cell_id":id,"kind":kind}));}
                }
            },
            _=>{},
        }
        let a=before.filter(|c|c.kind=="code");
        let b=after.filter(|c|c.kind=="code");
        if a.is_none() && b.is_none() {continue;}
        if before.into_iter().chain(after).any(|c|c.identity_quality!="explicit") {
            diagnostics.push(format!("identity_limited:{id}"));
        }
        if a.into_iter().chain(b).any(|c|c.status!="ok") {
            diagnostics.push(format!("comparison_incomplete:{id}")); continue;
        }
        if a.into_iter().chain(b).any(duplicate_symbol_identity) {
            diagnostics.push(format!("ambiguous_symbol_identity:{id}")); continue;
        }
        // Language/type changes are conservative removal + addition, never cross-language rename inference.
        let separate=matches!((a,b),(Some(x),Some(y)) if x.language!=y.language);
        if separate {
            if let Some(c)=a {requests.push(json!({"path":transport_path(left,c),"kind":"D","left":c.symbols,"right":[]}));contexts.push((Some(c),None));}
            if let Some(c)=b {requests.push(json!({"path":transport_path(right,c),"kind":"A","left":[],"right":c.symbols}));contexts.push((None,Some(c)));}
        } else {
            let (doc,cell)=if let Some(c)=b {(right,c)} else {(left,a.unwrap())};
            requests.push(json!({"path":transport_path(doc,cell),"kind":if a.is_none() {"A"} else if b.is_none() {"D"} else {"M"},
                "left":a.map(|c|c.symbols.clone()).unwrap_or_default(),"right":b.map(|c|c.symbols.clone()).unwrap_or_default()}));
            contexts.push((a,b));
        }
    }
    let results=native(json!({"op":"compare","pairs":requests}));
    let mut changes=Vec::new();
    for ((a,b),result) in contexts.into_iter().zip(results.as_array().unwrap()) {
        let cell_id=b.or(a).unwrap().id.clone();
        for d in result["diagnostics"].as_array().unwrap() {
            diagnostics.push(format!("matcher:{cell_id}:{d}"));
        }
        for delta in result["changes"].as_array().unwrap() {
            let (doc,cell)=if delta["change_kind"]=="deleted" {(left,a.unwrap())} else {(right,b.unwrap())};
            changes.push(json!({"cell_id":cell_id,"source_ref":source_ref(doc,cell,&delta["symbol"]),
                "before_cell_source_sha256":a.map(|c|c.source_sha256.as_str()),
                "after_cell_source_sha256":b.map(|c|c.source_sha256.as_str()),
                "native_transport_delta":delta}));
        }
    }
    json!({"changes":changes,"cell_changes":structures,"diagnostics":diagnostics,
        "coverage":if diagnostics.is_empty() {"complete_for_poc_languages"} else {"partial"},
        "native_delta_paths_are_transport_only":true})
}
fn make_code_cell(id: &str, lang: &str, source: Value) -> Value {
    json!({"cell_type":"code","id":id,"metadata":{"spur":{"code_type":lang}},"source":source,"outputs":[],"execution_count":null})
}
