fn resolve_source_ref(doc: &PocDocument,reference: &Value) -> Result<String,String> {
    if reference["snapshot_id"]!=doc.snapshot || reference["notebook_path"]!=doc.notebook
        || reference["notebook_source_sha256"]!=doc.source_sha256 {return Err("document_context_mismatch".into());}
    if reference["coordinate_space"]!="decoded_code_cell_utf8" {return Err("coordinate_frame_mismatch".into());}
    let cell=doc.cells.iter().find(|c|reference["cell_id"]==c.id).ok_or("missing_cell")?;
    if reference["cell_source_sha256"]!=cell.source_sha256 || reference["cell_language"]!=json!(cell.language) {
        return Err("cell_context_mismatch".into());
    }
    let start=reference["byte_start"].as_u64().ok_or("missing_start")? as usize;
    let end=reference["byte_end"].as_u64().ok_or("missing_end")? as usize;
    let span=cell.source.get(start..end).ok_or("invalid_cell_range")?;
    let start_line=cell.source[..start].bytes().filter(|b|*b==b'\n').count()+1;
    let end_line=cell.source[..end].bytes().filter(|b|*b==b'\n').count()+1;
    if reference["line_start"]!=json!(start_line) || reference["line_end"]!=json!(end_line) {
        return Err("line_coordinate_mismatch".into());
    }
    Ok(span.to_owned())
}
