#[derive(Clone,Debug)]
struct PreparedRust { analysis: String, directives: Vec<String> }
fn prepare_rust_header(source: &str) -> Result<PreparedRust,String> {
    let mut analysis=Vec::with_capacity(source.len());
    let mut directives=Vec::new();
    let mut in_header=true;
    for line in source.split_inclusive('\n') {
        let trimmed=line.trim();
        if in_header && trimmed.starts_with(":dep ") {
            if trimmed.ends_with('\\') || trimmed.ends_with('{') {return Err("unsupported_multiline_dependency_directive".into());}
            directives.push(trimmed.to_owned());
            analysis.extend(line.as_bytes().iter().map(|b|if *b==b'\n'||*b==b'\r' {*b} else {b' '}));
        } else {
            if in_header && trimmed.starts_with(':') && !trimmed.starts_with("::") {return Err("unsupported_kernel_directive".into());}
            if !trimmed.is_empty() {in_header=false;}
            analysis.extend_from_slice(line.as_bytes());
        }
    }
    let analysis=String::from_utf8(analysis).unwrap();
    assert_eq!(analysis.len(),source.len());
    let breaks=|s:&str|s.bytes().enumerate().filter_map(|(i,b)|if b==b'\n'||b==b'\r'{Some(i)}else{None}).collect::<Vec<_>>();
    assert_eq!(breaks(&analysis),breaks(source));
    Ok(PreparedRust{analysis,directives})
}
fn index_kernel_notebook(snapshot: &str,path: &str,source: &str) -> Result<(PocNotebook,Vec<Value>),String> {
    let raw:Value=serde_json::from_str(source).map_err(|e|e.to_string())?;
    let mut doc=normalize_notebook(snapshot,path,source)?;
    let originals:BTreeMap<String,(String,String)>=doc.cells.iter().map(|c|(c.id.clone(),(c.source.clone(),c.source_sha256.clone()))).collect();
    let mut preprocessing=Vec::new();
    for cell in &mut doc.cells {
        if cell.kind=="code"&&cell.language.as_deref()==Some("rust") {
            match prepare_rust_header(&cell.source) {
                Ok(p)=>{
                    preprocessing.push(json!({"cell_id":cell.id,"policy":"evcxr-leading-dep-mask-v1","directives":p.directives,
                        "original_source_sha256":cell.source_sha256,"analysis_source_sha256":sha256(&p.analysis),
                        "coordinate_map":"identity_utf8_byte_offsets","original_bytes":cell.source.len(),"analysis_bytes":p.analysis.len()}));
                    cell.source=p.analysis;cell.source_sha256=sha256(&cell.source);
                },
                Err(e)=>{
                    cell.status="unsupported_directive".into();cell.diagnostics.push(e.clone());
                    doc.diagnostics.push(format!("{e}:{}",cell.id));
                }
            }
        }
    }
    doc=extract_document(doc);
    for cell in &mut doc.cells {
        let (source,hash)=originals.get(&cell.id).unwrap();
        cell.source=source.clone();cell.source_sha256=hash.clone();assert_cell_ranges(cell);
    }
    Ok((PocNotebook{document:doc,metadata:raw.get("metadata").cloned().unwrap_or(json!({}))},preprocessing))
}
fn compare_kernel_notebooks(left: &(PocNotebook,Vec<Value>),right: &(PocNotebook,Vec<Value>)) -> Value {
    let mut result=compare_notebooks(&left.0,&right.0);
    let before:BTreeMap<String,Value>=left.1.iter().map(|r|(r["cell_id"].as_str().unwrap().to_owned(),r["directives"].clone())).collect();
    let after:BTreeMap<String,Value>=right.1.iter().map(|r|(r["cell_id"].as_str().unwrap().to_owned(),r["directives"].clone())).collect();
    for id in before.keys().chain(after.keys()).collect::<BTreeSet<_>>() {
        if before.get(id)!=after.get(id) {
            result["cell_changes"].as_array_mut().unwrap().push(json!({"cell_id":id,"kind":"dependency_directives_changed","before":before.get(id),"after":after.get(id)}));
        }
    }
    result
}
